import test from "node:test";
import assert from "node:assert/strict";
import { reviewRoute, reviewMode } from "../src/route.js";
import { riskFor } from "../src/risk.js";

const file = (filename: string, additions: number, deletions = 0) => ({ filename, additions, deletions });
const FCP = {
  high: { paths: ["cloud/rhinoCloud/rhinoCore/migrations/**", ".github/workflows/**"], reason: "schema change or CI" },
  low: { paths: ["**/*.md", "**/*.stories.tsx", "**/tests/**"], reason: "docs or tests only" },
};

test("a docs-only PR is reviewed at low effort", () => {
  assert.equal(reviewRoute([file("docs/setup.md", 30)]).effort, "low");
});
test("a lockfile does not count towards size", () => {
  assert.deepEqual(reviewRoute([file("frontend/package-lock.json", 5000), file("frontend/src/a.ts", 10)]),
    { model: "claude-opus-5-5", effort: "medium", reason: "10 changed lines" });
});
test("a migration makes the PR risk:high, and deep mode follows", () => {
  const risk = riskFor([file("cloud/rhinoCloud/rhinoCore/migrations/0042_add_index.py", 20)], FCP);
  assert.deepEqual(risk, { tier: "high", reasons: ["1 file(s): schema change or CI"] });
  assert.equal(reviewMode({ risk: risk.tier, changedLines: 20 }).mode, "deep");
});
test("900 lines of ordinary code raise med to high", () => {
  assert.deepEqual(riskFor([file("frontend/src/pages/Big.tsx", 900)], FCP), { tier: "high", reasons: ["900 changed lines"] });
});

